import UIKit
import Display

/// Template artwork keeps the exact tint chosen by each native Premium slot.
public enum ConceptBadgeArt {
    private static let cache = NSCache<NSString, UIImage>()
    public static func image(badge: ConceptBadge, height: CGFloat) -> UIImage {
        let height = max(12, min(40, (height * 2).rounded() / 2))
        let key = "\(badge.role.rawValue).\(badge.glyph.rawValue).\(height)" as NSString
        if let image = cache.object(forKey: key) { return image }
        let renderer = UIGraphicsImageRenderer(size: CGSize(width: height, height: height))
        let image = renderer.image { renderer in
            let context = renderer.cgContext
            let bounds = CGRect(x: 0, y: 0, width: height, height: height)
            var glyphBounds = bounds.insetBy(dx: height * 0.02, dy: height * 0.02)
            if badge.hasRosette {
                let path = UIBezierPath()
                // Smooth scallops like the native verified seal, with a soft tint.
                let count = 160
                for i in 0...count {
                    let angle = CGFloat(i) / CGFloat(count) * .pi * 2 - .pi / 2
                    let radius = height * (0.45 + 0.035 * cos(angle * 10))
                    let point = CGPoint(x: height / 2 + cos(angle) * radius, y: height / 2 + sin(angle) * radius)
                    if i == 0 { path.move(to: point) } else { path.addLine(to: point) }
                }
                path.close(); UIColor.white.withAlphaComponent(0.24).setFill(); path.fill()
                glyphBounds = bounds.insetBy(dx: height * 0.22, dy: height * 0.22)
            }
            UIColor.white.setFill()
            if badge.glyph == .butterfly, let path = Self.butterflyPath {
                let source = path.boundingBoxOfPath
                let scale = min(glyphBounds.width / source.width, glyphBounds.height / source.height)
                context.saveGState()
                context.translateBy(x: glyphBounds.midX - source.midX * scale, y: glyphBounds.midY - source.midY * scale)
                context.scaleBy(x: scale, y: scale)
                context.addPath(path); context.fillPath(); context.restoreGState()
            } else {
                let name: String
                switch badge.glyph { case .heart: name = "heart.fill"; case .star: name = "star.fill"; case .sparkle: name = "sparkles"; case .butterfly: name = "sparkles" }
                let configuration = UIImage.SymbolConfiguration(pointSize: glyphBounds.height, weight: .semibold)
                if let glyph = UIImage(systemName: name, withConfiguration: configuration)?.withTintColor(.white, renderingMode: .alwaysOriginal) {
                    let scale = min(glyphBounds.width / glyph.size.width, glyphBounds.height / glyph.size.height)
                    let size = CGSize(width: glyph.size.width * scale, height: glyph.size.height * scale)
                    glyph.draw(in: CGRect(x: glyphBounds.midX - size.width / 2, y: glyphBounds.midY - size.height / 2, width: size.width, height: size.height))
                }
            }
        }.withRenderingMode(.alwaysTemplate)
        cache.countLimit = 128; cache.setObject(image, forKey: key)
        return image
    }
