public final class ConceptBadgeView: UIImageView {
    public var changed: (() -> Void)?
    public var activated: ((String) -> Void)? {
        didSet { self.isUserInteractionEnabled = self.activated != nil; self.isAccessibilityElement = self.activated != nil }
    }
    private var peerId: String?
    @objc private func tapped() {
        if let peerId = self.peerId { self.activated?(peerId) }
    }
    public override func accessibilityActivate() -> Bool {
        guard self.activated != nil, self.peerId != nil else { return false }
        self.tapped()
        return true
    }
    private var observer: NSObjectProtocol?
    public init() {
        super.init(frame: .zero)
        self.contentMode = .scaleAspectFit
        self.isAccessibilityElement = false
        self.isUserInteractionEnabled = false
        self.addGestureRecognizer(UITapGestureRecognizer(target: self, action: #selector(self.tapped)))
        self.accessibilityTraits = .button
        self.accessibilityLabel = "Concept badge information"
        self.observer = NotificationCenter.default.addObserver(forName: ConceptBadgeService.changed, object: nil, queue: .main) { [weak self] _ in self?.changed?() }
    }
    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }
    deinit { if let observer { NotificationCenter.default.removeObserver(observer) } }
    @discardableResult public func update(peerId: String?, color: UIColor, height: CGFloat) -> CGFloat {
        self.peerId = peerId
        guard let peerId, let badge = ConceptBadgeService.shared.badge(peerId: peerId) else { self.image = nil; self.isHidden = true; return 0 }
        self.image = ConceptBadgeArt.image(badge: badge, height: height)
        self.tintColor = color; self.isHidden = false
        return self.image?.size.width ?? 0
    }
}
